insert into passages (id, text, difficulty_level, b, active) values
('0813c8b7-5859-4437-b816-681608ace606', 'As cities continue to grow, urban planners face increasing pressure to balance development with the preservation of green spaces. Parks, gardens, and tree-lined streets are often viewed as amenities, yet research increasingly suggests they serve essential functions beyond recreation. Green spaces help regulate urban temperatures by reducing the heat absorbed by concrete and asphalt, a phenomenon known as the urban heat island effect. They also improve air quality by filtering pollutants and provide habitats for wildlife that would otherwise struggle to survive in dense urban environments. Furthermore, studies have linked access to green spaces with improved mental health, as time spent in natural settings has been shown to reduce stress and anxiety. Despite these documented benefits, green spaces are frequently the first areas sacrificed when cities expand, largely because they generate less immediate economic return than commercial or residential development.', 4, 1.0, true),
('a62091fc-986a-472a-a261-8a659ab696d9', 'With the widespread use of computers, tablets, and smartphones, handwriting has become a less essential skill in many people''s daily lives. Some educators argue that this shift is simply a natural adaptation to technological progress, comparable to how calculators reduced the emphasis on manual arithmetic. Others, however, express concern that abandoning handwriting instruction too early may have unintended consequences. Research suggests that the physical act of writing by hand engages different cognitive processes than typing, potentially strengthening memory retention and fine motor skills, particularly in young children. Additionally, cursive handwriting, once a standard part of school curricula, has been dropped by many education systems altogether, raising concerns among historians and archivists about future generations'' ability to read historical documents written in cursive script. As debates continue, some schools have adopted a compromise, teaching basic handwriting skills while dedicating most instructional time to digital literacy.', 4, 1.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('53603d98-8afc-4c22-9b1c-c62f614f3b07', 'sentence_completion', 'The company had to ___ additional funds to cover the unexpected repairs.', NULL, '[{"id": "b", "text": "allocate"}, {"id": "d", "text": "hide"}, {"id": "c", "text": "waste"}, {"id": "a", "text": "ignore"}]'::jsonb, 0, '{"strategy": "cover the unexpected repairs = לכסות תיקונים בלתי צפויים. מה עושים עם כספים למטרה כזו?", "correct_reason": "allocate = להקצות. מקצים כספים למטרה ספציפית כמו תיקונים.", "options_analysis": ["נכון! allocate = להקצות — פעולה נכונה לכיסוי הוצאה מסוימת", "hide = להסתיר — לא קשור לכספים לתיקון", "waste = לבזבז — הפוך מהקצאה מכוונת", "ignore = להתעלם מ- — לא רלוונטי לתיקונים דחופים"]}', 0.96, 1.0, 0.25, 4, 'ai', NULL, true),
('bdcc3057-32b2-4496-97a4-e96b65032ab7', 'sentence_completion', 'Her explanation was so ___ that no one doubted her honesty.', NULL, '[{"id": "d", "text": "rude"}, {"id": "b", "text": "convincing"}, {"id": "c", "text": "confusing"}, {"id": "a", "text": "silent"}]'::jsonb, 1, '{"strategy": "no one doubted her honesty = אף אחד לא פקפק בכנותה. איזה הסבר משכנע כל כך?", "correct_reason": "convincing = משכנע. הסבר משכנע מונע ספק.", "options_analysis": ["rude = גסה — לא קשור לאמינות", "נכון! convincing = משכנע — מסביר למה לא היה ספק", "confusing = מבלבל — הפוך, בלבול מעורר ספק", "silent = שקטה — לא מתאר הסבר כלל"]}', 1.13, 1.0, 0.25, 4, 'ai', NULL, true),
('915746f4-8171-4ec6-aec4-650f7754f52f', 'sentence_completion', 'The new policy proved ___ among employees, sparking heated debate.', NULL, '[{"id": "d", "text": "boring"}, {"id": "c", "text": "simple"}, {"id": "a", "text": "controversial"}, {"id": "b", "text": "popular"}]'::jsonb, 2, '{"strategy": "sparking heated debate = הצית ויכוח סוער. איזו מדיניות מעוררת ויכוח?", "correct_reason": "controversial = שנוי במחלוקת. מדיניות כזו מעוררת ויכוחים.", "options_analysis": ["boring = משעממת — לא מעוררת ויכוח", "simple = פשוטה — לא מעוררת ויכוח", "נכון! controversial = שנוי במחלוקת — מסביר את הוויכוח הסוער", "popular = פופולרית — פופולריות לא מסבירה ויכוח סוער"]}', 0.96, 1.0, 0.25, 4, 'ai', NULL, true),
('fab4296d-9819-40f5-817b-3c831a8d545c', 'sentence_completion', 'Experts ___ that the new law will reduce traffic accidents significantly.', NULL, '[{"id": "a", "text": "forget"}, {"id": "d", "text": "deny"}, {"id": "b", "text": "oppose"}, {"id": "c", "text": "anticipate"}]'::jsonb, 3, '{"strategy": "will reduce = תפחית. מה עושים מומחים לגבי תוצאה עתידית צפויה?", "correct_reason": "anticipate = צופים. מומחים צופים תוצאה עתידית.", "options_analysis": ["forget = שוכחים — לא רלוונטי לניתוח מומחים", "deny = מכחישים — לא מתאים לתחזית חיובית", "oppose = מתנגדים — לא מתאר תחזית", "נכון! anticipate = צופים — פעולה טבעית של מומחים לגבי עתיד"]}', 1.54, 1.0, 0.25, 4, 'ai', NULL, true),
('479cbec4-41ff-47b3-907b-6e2478a1902b', 'sentence_completion', 'Although the plan sounded good in theory, it was not ___ in practice.', NULL, '[{"id": "d", "text": "feasible"}, {"id": "c", "text": "expensive"}, {"id": "a", "text": "illegal"}, {"id": "b", "text": "popular"}]'::jsonb, 0, '{"strategy": "sounded good in theory but not ___ in practice = טוב בתיאוריה אך לא בר-ביצוע במעשה.", "correct_reason": "feasible = בר-ביצוע. הניגוד בין תיאוריה למעשה מתאים ל''לא ישים''.", "options_analysis": ["נכון! feasible = בר-ביצוע — הניגוד המתאים לתיאוריה מול מעשה", "expensive = יקר — לא הניגוד המתבקש לתיאוריה טובה", "illegal = לא חוקי — לא מוזכר הקשר משפטי", "popular = פופולרית — לא קשור ליישום מעשי"]}', 1.29, 1.0, 0.25, 4, 'ai', NULL, true),
('694eb1d3-eecf-4df4-a640-a200b3edaa9f', 'sentence_completion', 'The manager was ___ about hiring someone without any experience.', NULL, '[{"id": "b", "text": "eager"}, {"id": "a", "text": "reluctant"}, {"id": "c", "text": "careless"}, {"id": "d", "text": "thrilled"}]'::jsonb, 1, '{"strategy": "hiring someone without experience = לגייס מישהו בלי ניסיון. איך מנהל בדרך כלל מרגיש לגבי זה?", "correct_reason": "reluctant = מהסס. חוסר ניסיון גורם להיסוס בגיוס.", "options_analysis": ["eager = להוט — הפוך מהיסוס טבעי", "נכון! reluctant = מהסס — תגובה טבעית לחוסר ניסיון", "careless = חסר זהירות — הפוך, מנהל זהיר דווקא מהסס", "thrilled = נרגש מאוד — לא מתאים להיסוס"]}', 1.09, 1.0, 0.25, 4, 'ai', NULL, true),
('5a4e4d89-3f9b-4849-884e-2bc376d29f61', 'sentence_completion', 'The report provided a ___ overview of the company''s financial situation.', NULL, '[{"id": "a", "text": "false"}, {"id": "d", "text": "brief"}, {"id": "c", "text": "comprehensive"}, {"id": "b", "text": "vague"}]'::jsonb, 2, '{"strategy": "overview = סקירה. איזו סקירה נותנת תמונה מלאה של המצב הפיננסי?", "correct_reason": "comprehensive = מקיפה. סקירה מקיפה מכסה את כל הפרטים החשובים.", "options_analysis": ["false = כוזבת — לא הגיוני לדוח רשמי", "brief = תמציתית — הפוך מ''מקיפה''", "נכון! comprehensive = מקיפה — מתאימה לדוח פיננסי מלא", "vague = מעורפלת — לא מתאים לדוח פיננסי אמין"]}', 1.28, 1.0, 0.25, 4, 'ai', NULL, true),
('78d1c3f6-ea7f-4eea-8606-14d2b47f9b45', 'sentence_completion', 'Many scientists remain ___ about the new theory until more evidence is found.', NULL, '[{"id": "a", "text": "certain"}, {"id": "b", "text": "excited"}, {"id": "d", "text": "careless"}, {"id": "c", "text": "skeptical"}]'::jsonb, 3, '{"strategy": "until more evidence is found = עד שתימצא עוד הוכחה. איך מדענים מתייחסים לתיאוריה לא מוכחת?", "correct_reason": "skeptical = סקפטיים/מפקפקים. חוסר הוכחות מוביל לספקנות מדעית.", "options_analysis": ["certain = בטוחים — סותר ''until more evidence is found''", "excited = נרגשים — לא מתאר גישה מדעית זהירה", "careless = חסרי זהירות — הפוך מגישה מדעית", "נכון! skeptical = ספקנים — גישה מדעית טבעית ללא הוכחות מספיקות"]}', 0.92, 1.0, 0.25, 4, 'ai', NULL, true),
('acd6a7f3-98f1-4a8e-b969-d1b698d310bf', 'sentence_completion', 'The court ruled that the evidence was not sufficient to ___ the claim.', NULL, '[{"id": "c", "text": "support"}, {"id": "b", "text": "hide"}, {"id": "a", "text": "deny"}, {"id": "d", "text": "create"}]'::jsonb, 0, '{"strategy": "not sufficient = לא מספיקה. הראיות לא הספיקו כדי לעשות מה לטענה?", "correct_reason": "support = לתמוך ב-. ראיות לא מספיקות לא יכולות לתמוך בטענה.", "options_analysis": ["נכון! support = לתמוך — ראיות משמשות לתמיכה או דחיית טענה", "hide = להסתיר — לא קשור לפסיקת בית משפט", "deny = להכחיש — לא מתאים להקשר של ''not sufficient to''", "create = ליצור — לא רלוונטי לראיות משפטיות"]}', 1.38, 1.0, 0.25, 4, 'ai', NULL, true),
('50e4c537-8896-4b32-b613-e82a1608dcbd', 'sentence_completion', 'The rising cost of housing has become a ___ concern for many families.', NULL, '[{"id": "d", "text": "minor"}, {"id": "a", "text": "considerable"}, {"id": "c", "text": "pleasant"}, {"id": "b", "text": "rare"}]'::jsonb, 1, '{"strategy": "rising cost = עלייה במחיר. עלייה משמעותית יוצרת דאגה מסוג מה?", "correct_reason": "considerable = משמעותית/ניכרת. עלייה חדה יוצרת דאגה משמעותית.", "options_analysis": ["minor = זניחה — הפוך מ''עלייה'' משמעותית", "נכון! considerable = משמעותית — מתאים לעלייה חדה במחירים", "pleasant = נעימה — לא מתאים לדאגה", "rare = נדירה — לא מתאר היקף דאגה"]}', 1.08, 1.0, 0.25, 4, 'ai', NULL, true),
('2d2d85aa-0216-4646-9e97-f0d1beb58989', 'sentence_completion', 'His argument seemed logical at first, but it was later ___ by new data.', NULL, '[{"id": "d", "text": "celebrated"}, {"id": "c", "text": "ignored"}, {"id": "b", "text": "undermined"}, {"id": "a", "text": "supported"}]'::jsonb, 2, '{"strategy": "seemed logical at first but later ___ = נראה הגיוני בהתחלה אך לאחר מכן... חפש ניגוד.", "correct_reason": "undermined = נחלש/נסתר. נתונים חדשים החלישו את הטיעון.", "options_analysis": ["celebrated = זכה לשבחים — לא הגיוני בהקשר של ניגוד", "ignored = הוזנח — לא מסביר השפעה של נתונים חדשים", "נכון! undermined = נחלש — הניגוד המתבקש אחרי ''but''", "supported = נתמך — סותר את מבנה הניגוד ''but''"]}', 1.0, 1.0, 0.25, 4, 'ai', NULL, true),
('7f251b1d-2f1b-4aac-99e3-3febb238092d', 'sentence_completion', 'It is ___ that prices will continue to rise if demand keeps increasing.', NULL, '[{"id": "d", "text": "impossible"}, {"id": "b", "text": "forbidden"}, {"id": "c", "text": "unlikely"}, {"id": "a", "text": "inevitable"}]'::jsonb, 3, '{"strategy": "if demand keeps increasing = אם הביקוש ימשיך לעלות. מה קורה למחירים במקרה כזה?", "correct_reason": "inevitable = בלתי נמנע. עלייה בביקוש מובילה בהכרח לעלייה במחירים.", "options_analysis": ["impossible = בלתי אפשרי — סותר את ההיגיון הכלכלי", "forbidden = אסור — לא רלוונטי לתהליך כלכלי", "unlikely = לא סביר — סותר את ההיגיון של המשפט", "נכון! inevitable = בלתי נמנע — מתאים לתהליך כלכלי טבעי"]}', 0.98, 1.0, 0.25, 4, 'ai', NULL, true),
('1b84d37c-2928-4ec2-9e29-eb9a731030d4', 'restatement', 'The report was written by the research team last month.', NULL, '[{"id": "b", "text": "The research team wrote the report last month."}, {"id": "a", "text": "The research team will write the report next month."}, {"id": "d", "text": "The report wrote itself last month."}, {"id": "c", "text": "Someone else wrote the report, not the research team."}]'::jsonb, 0, '{"strategy": "passive to active: נכתב ע''י הצוות -> הצוות כתב.", "correct_reason": "''the research team wrote the report'' = אותה עובדה בקול פעיל.", "options_analysis": ["נכון! אותה עובדה בדיוק, בקול פעיל במקום סביל", "''יכתבו בעתיד'' סותר ''last month''", "משפט חסר הגיון", "סותר את המקור — הצוות דווקא כתב אותו"]}', 1.29, 1.0, 0.25, 4, 'ai', NULL, true),
('a187b092-778e-4416-8de8-4031d548cc9d', 'restatement', 'If the weather improves, the trip will go ahead as planned.', NULL, '[{"id": "b", "text": "The weather has already improved, so the trip is cancelled."}, {"id": "d", "text": "The trip will go ahead as planned only if the weather improves."}, {"id": "c", "text": "The trip will be cancelled if the weather improves."}, {"id": "a", "text": "The trip will go ahead no matter what the weather is like."}]'::jsonb, 1, '{"strategy": "if...will = תנאי מסוג ראשון: השיפור הוא תנאי הכרחי לטיול.", "correct_reason": "''go ahead only if weather improves'' = משמר בדיוק את התנאי המקורי.", "options_analysis": ["סותר ''if'' — לא נאמר שכבר השתפר, וגם הטיול לא מבוטל", "נכון! משמר את התנאי המדויק — הטיול תלוי בשיפור", "הפוך — התנאי גורם לביטול במקום לקיום", "סותר את התנאי — במקור הטיול תלוי במזג האוויר"]}', 1.23, 1.0, 0.25, 4, 'ai', NULL, true),
('df2ff4f2-9a3e-4c72-8dd5-fa8e9036ae3b', 'restatement', 'This car is more expensive than that one, but it is also safer.', NULL, '[{"id": "d", "text": "That car is more expensive but safer."}, {"id": "b", "text": "Both cars cost the same amount."}, {"id": "a", "text": "That car is cheaper than this one, though less safe."}, {"id": "c", "text": "This car is cheaper and safer than that one."}]'::jsonb, 2, '{"strategy": "יחס השוואתי הפוך: המכונית הזו יקרה יותר ובטוחה יותר = ההיא זולה יותר ופחות בטוחה.", "correct_reason": "''that car is cheaper, though less safe'' = היפוך יחס נכון לשתי ההשוואות.", "options_analysis": ["הפוך תפקידים — במקור ''this'' יקרה יותר, לא ''that''", "סותר את קיום ההשוואה במקור", "נכון! היפוך נכון: ההיא זולה יותר ופחות בטוחה", "סותר — במקור המכונית הזו יקרה יותר, לא זולה"]}', 1.59, 1.0, 0.25, 4, 'ai', NULL, true),
('563c5de9-5129-4d57-bd37-41de9d70832d', 'restatement', 'The students were told to submit their assignments by Friday.', NULL, '[{"id": "c", "text": "The students were told they could submit assignments anytime."}, {"id": "a", "text": "The teacher submitted the assignments for the students."}, {"id": "d", "text": "The students decided on their own to submit assignments early."}, {"id": "b", "text": "The students were instructed to hand in their assignments no later than Friday."}]'::jsonb, 3, '{"strategy": "were told to submit by Friday = קיבלו הוראה להגיש עד יום שישי.", "correct_reason": "''instructed to hand in no later than Friday'' = אותה הוראה בדיוק, בניסוח שונה.", "options_analysis": ["סותר ''by Friday'' שמציין מועד סופי", "המורה לא הגיש עבורם, הם קיבלו הוראה להגיש בעצמם", "סותר — לא הייתה החלטה עצמאית, אלא הוראה", "נכון! אותה הוראה בדיוק: להגיש עד יום שישי לכל המאוחר"]}', 1.48, 1.0, 0.25, 4, 'ai', NULL, true),
('04740d63-1ac9-47d9-9141-a4fbd7f01d1f', 'restatement', 'Not only did she pass the exam, but she also received the highest score.', NULL, '[{"id": "b", "text": "She not only passed the exam but also achieved the top score."}, {"id": "c", "text": "She failed the exam despite trying her best."}, {"id": "a", "text": "She passed the exam but received a low score."}, {"id": "d", "text": "She received the highest score without taking the exam."}]'::jsonb, 0, '{"strategy": "not only...but also = לא רק... אלא גם. הצליחה וגם קיבלה את הציון הגבוה ביותר.", "correct_reason": "''not only passed but also achieved the top score'' = אותה משמעות בדיוק.", "options_analysis": ["נכון! אותה משמעות בדיוק: עברה והשיגה את הציון הגבוה ביותר", "סותר לגמרי — במקור היא עברה בהצלחה", "סותר ''highest score''", "סותר — היא כן ניגשה למבחן"]}', 1.08, 1.0, 0.25, 4, 'ai', NULL, true),
('f2f40d77-9b6c-4795-ad1b-cf7a531e46f0', 'restatement', 'The longer he practiced, the better he became at chess.', NULL, '[{"id": "a", "text": "He became worse at chess the more he practiced."}, {"id": "d", "text": "His skill at chess improved the more he practiced."}, {"id": "c", "text": "He stopped practicing chess after becoming skilled."}, {"id": "b", "text": "His chess skill had no connection to how much he practiced."}]'::jsonb, 1, '{"strategy": "the longer...the better = ככל ש-...כך. יחס ישר בין תרגול לשיפור.", "correct_reason": "''skill improved the more he practiced'' = אותו יחס ישר בדיוק.", "options_analysis": ["הפוך — ''worse'' סותר ''better''", "נכון! אותו יחס ישר: יותר תרגול = יותר שיפור", "לא נאמר במקור כלל", "סותר את היחס הישיר שמתואר במקור"]}', 0.96, 1.0, 0.25, 4, 'ai', NULL, true),
('582d63b7-689f-4c43-a786-1a39d662487b', 'restatement', 'She refuses to speak to him again until he offers an apology.', NULL, '[{"id": "a", "text": "She will never speak to him again, regardless of an apology."}, {"id": "b", "text": "She will speak to him again even if he does not apologize."}, {"id": "c", "text": "She will not speak to him again unless he apologizes."}, {"id": "d", "text": "He has already apologized, so she is speaking to him."}]'::jsonb, 2, '{"strategy": "until he offers an apology = עד שיתנצל. תנאי לחידוש הקשר.", "correct_reason": "''will not speak unless he apologizes'' = until=unless...not, אותו תנאי בדיוק.", "options_analysis": ["סותר — במקור יש תנאי, לא סירוב מוחלט", "סותר את התנאי — במקור התנאי הוא הכרחי", "נכון! אותו תנאי בדיוק: לא תדבר איתו עד/אלא אם יתנצל", "לא נאמר במקור שכבר התנצל"]}', 1.45, 1.0, 0.25, 4, 'ai', NULL, true),
('4838b4a7-14ca-4bf4-9d5a-30f249e6bdc9', 'restatement', 'The new law, which was passed last year, has already reduced pollution levels.', NULL, '[{"id": "a", "text": "The law has had no effect on pollution levels so far."}, {"id": "c", "text": "The new law will be passed next year to reduce pollution."}, {"id": "b", "text": "Pollution levels increased after the new law was passed."}, {"id": "d", "text": "Pollution levels have already dropped since the new law was passed last year."}]'::jsonb, 3, '{"strategy": "has already reduced = כבר הפחית. השפעה שכבר קרתה.", "correct_reason": "''levels have already dropped since the law was passed'' = אותה עובדה בדיוק בזמן ובכיוון.", "options_analysis": ["סותר לגמרי — במקור כבר הייתה השפעה", "סותר ''last year'' — החוק כבר עבר, לא עתידי", "הפוך — ''increased'' סותר ''reduced''", "נכון! אותה עובדה בדיוק: ירידה כבר קרתה מאז החוק"]}', 1.23, 1.0, 0.25, 4, 'ai', NULL, true),
('2dc5c5fd-2774-44ab-ba24-de0f552310b7', 'restatement', 'Had she known about the traffic, she would have left earlier.', NULL, '[{"id": "b", "text": "She left later than she should have because she did not know about the traffic."}, {"id": "a", "text": "She knew about the traffic and left early."}, {"id": "d", "text": "The traffic had no effect on when she left."}, {"id": "c", "text": "She left early even though she knew about the traffic."}]'::jsonb, 0, '{"strategy": "תנאי שלישי הפוך: לא ידעה, ולכן לא יצאה מוקדם יותר.", "correct_reason": "''left later because did not know'' = המשמעות ההפוכה הנכונה של התנאי השלישי.", "options_analysis": ["נכון! תנאי שלישי הפוך: לא ידעה, לכן יצאה מאוחר מדי", "סותר — במקור היא לא ידעה", "סותר — לתנאי יש השפעה ברורה על זמן היציאה", "סותר — במקור היא לא ידעה כלל"]}', 1.15, 1.0, 0.25, 4, 'ai', NULL, true),
('3b6d25dd-95eb-43fa-bb2b-8ad66e72054f', 'restatement', 'The higher the demand, the higher the price tends to rise.', NULL, '[{"id": "b", "text": "Prices tend to fall as demand increases."}, {"id": "c", "text": "Prices tend to rise as demand increases."}, {"id": "d", "text": "Demand has no effect on prices."}, {"id": "a", "text": "Prices rise regardless of demand."}]'::jsonb, 1, '{"strategy": "the higher...the higher = יחס ישר בין ביקוש למחיר.", "correct_reason": "''prices rise as demand increases'' = אותו יחס ישר בדיוק.", "options_analysis": ["הפוך — ''fall'' סותר ''rise''", "נכון! אותו יחס ישר: ביקוש עולה, מחיר עולה", "סותר את היחס המתואר במקור", "סותר — במקור יש קשר ישיר לביקוש"]}', 0.93, 1.0, 0.25, 4, 'ai', NULL, true),
('ed6f25f8-267b-4134-be42-7bb9ea2c69b5', 'restatement', 'Despite receiving several warnings, he continued to break the rules.', NULL, '[{"id": "b", "text": "He broke the rules only because no one warned him."}, {"id": "a", "text": "He received warnings after he stopped breaking the rules."}, {"id": "d", "text": "He kept breaking the rules even after being warned several times."}, {"id": "c", "text": "He stopped breaking the rules after one warning."}]'::jsonb, 2, '{"strategy": "despite receiving warnings...continued = למרות אזהרות, המשיך.", "correct_reason": "''kept breaking rules even after being warned several times'' = אותה משמעות בדיוק.", "options_analysis": ["סותר — במקור הוא כן קיבל אזהרות", "הופך את סדר האירועים", "נכון! אותה משמעות בדיוק: המשיך למרות אזהרות חוזרות", "סותר ''continued'' — במקור הוא לא הפסיק"]}', 1.39, 1.0, 0.25, 4, 'ai', NULL, true),
('f79f04c2-d7dc-472a-9327-fca806c98845', 'restatement', 'The sooner you apply, the better your chances of being accepted.', NULL, '[{"id": "d", "text": "The timing of your application makes no difference."}, {"id": "c", "text": "Applying later increases your chances of acceptance."}, {"id": "a", "text": "You must apply exactly on the deadline to be accepted."}, {"id": "b", "text": "Applying earlier increases your chances of acceptance."}]'::jsonb, 3, '{"strategy": "the sooner...the better = ככל שמוקדם יותר, כך טוב יותר.", "correct_reason": "''applying earlier increases your chances'' = אותו יחס ישר בדיוק.", "options_analysis": ["סותר את היחס המתואר במקור", "הפוך — ''later'' סותר ''sooner''", "לא נאמר במקור, וגם לא הגיוני", "נכון! אותו יחס ישר: הגשה מוקדמת יותר = סיכוי טוב יותר"]}', 0.95, 1.0, 0.25, 4, 'ai', NULL, true),
('4f5bdcc7-63c0-4742-96f9-a242f8424475', 'reading_comprehension', 'What is the passage mainly about?', '0813c8b7-5859-4437-b816-681608ace606', '[{"id": "c", "text": "The important but often overlooked benefits of urban green spaces"}, {"id": "b", "text": "Why wildlife cannot survive in cities"}, {"id": "d", "text": "A history of park design in major cities"}, {"id": "a", "text": "The economic advantages of commercial development"}]'::jsonb, 0, '{"strategy": "שאלת רעיון מרכזי — הפסקה סוקרת תפקידים חשובים של שטחים ירוקים שלרוב מתעלמים מהם.", "correct_reason": "כל הפסקה עוסקת בתועלות השטחים הירוקים מעבר לפנאי, ובכך שהם נפגעים ראשונים בפיתוח.", "options_analysis": ["נכון! התועלות החשובות אך המוזנחות של שטחים ירוקים = הנושא הכולל", "לא נאמר בפסקה, ואף סותר — יש להם בתי גידול בערים", "לא מוזכר כלל בפסקה", "לא הנושא, הפוך למגמה שמתוארת בפסקה"]}', 0.96, 1.0, 0.25, 4, 'ai', NULL, true),
('535e8556-5c53-48ce-92aa-99bad3bb142a', 'reading_comprehension', 'What is the urban heat island effect, according to the passage?', '0813c8b7-5859-4437-b816-681608ace606', '[{"id": "b", "text": "A disease caused by lack of green spaces"}, {"id": "d", "text": "The increased heat absorbed by concrete and asphalt in cities"}, {"id": "c", "text": "A type of pollution caused by traffic"}, {"id": "a", "text": "A method used to cool city buildings"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את ההגדרה המדויקת בפסקה.", "correct_reason": "הפסקה אומרת: ''reducing the heat absorbed by concrete and asphalt, a phenomenon known as the urban heat island effect''.", "options_analysis": ["לא נאמר בפסקה", "נכון! ההגדרה המדויקת מהפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה"]}', 1.16, 1.0, 0.25, 4, 'ai', NULL, true),
('3d75be81-5e81-4179-ac12-aba3a45481ea', 'reading_comprehension', 'The word "amenities" in the passage most closely means:', '0813c8b7-5859-4437-b816-681608ace606', '[{"id": "b", "text": "legal requirements"}, {"id": "a", "text": "sources of pollution"}, {"id": "c", "text": "features that provide comfort or convenience"}, {"id": "d", "text": "financial investments"}]'::jsonb, 2, '{"strategy": "אוצר מילים בהקשר — ''often viewed as amenities'' מתייחס לתכונות נעימות/נוחות.", "correct_reason": "amenities = מתקנים/תכונות שמעניקים נוחות או הנאה.", "options_analysis": ["לא קשור למשמעות המילה", "לא קשור למשמעות המילה", "נכון! amenities = תכונות של נוחות והנאה", "לא קשור למשמעות המילה"]}', 1.36, 1.0, 0.25, 4, 'ai', NULL, true),
('705d631a-2513-4e14-be22-d0ace07ac901', 'reading_comprehension', 'According to the passage, how do green spaces affect mental health?', '0813c8b7-5859-4437-b816-681608ace606', '[{"id": "c", "text": "Green spaces have no documented effect on mental health"}, {"id": "d", "text": "Green spaces are mainly used for physical exercise, not mental health"}, {"id": "b", "text": "Green spaces increase stress due to maintenance costs"}, {"id": "a", "text": "Time spent in natural settings has been shown to reduce stress and anxiety"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את הקשר לבריאות הנפש בפסקה.", "correct_reason": "הפסקה אומרת: ''time spent in natural settings has been shown to reduce stress and anxiety''.", "options_analysis": ["סותר את הפסקה — יש השפעה מתועדת", "לא נאמר בפסקה כהגבלה יחידה", "לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה"]}', 1.04, 1.0, 0.25, 4, 'ai', NULL, true),
('58fae3ec-88ac-46e8-b653-4da24d55b23a', 'reading_comprehension', 'Why are green spaces often removed as cities expand, according to the passage?', '0813c8b7-5859-4437-b816-681608ace606', '[{"id": "d", "text": "They generate less immediate economic return than commercial or residential development"}, {"id": "b", "text": "They are more expensive to build than commercial buildings"}, {"id": "a", "text": "Residents generally prefer commercial development"}, {"id": "c", "text": "Wildlife habitats are considered a legal obstacle to expansion"}]'::jsonb, 0, '{"strategy": "שאלת סיבה — חפש את המשפט האחרון בפסקה.", "correct_reason": "הפסקה אומרת: ''largely because they generate less immediate economic return than commercial or residential development''.", "options_analysis": ["נכון! הסיבה המדויקת מהפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה"]}', 1.24, 1.0, 0.25, 4, 'ai', NULL, true),
('2b852f71-8e77-4597-9262-ddd89b68ce9a', 'reading_comprehension', 'Which of the following is NOT mentioned as a benefit of green spaces in the passage?', '0813c8b7-5859-4437-b816-681608ace606', '[{"id": "a", "text": "Improving air quality"}, {"id": "d", "text": "Increasing property values in nearby neighborhoods"}, {"id": "b", "text": "Regulating urban temperatures"}, {"id": "c", "text": "Providing habitats for wildlife"}]'::jsonb, 1, '{"strategy": "שאלת NOT — חפש מה לא הוזכר מבין ארבע האפשרויות.", "correct_reason": "הפסקה מזכירה: ויסות טמפרטורה, איכות אוויר, בתי גידול לחיות בר, ובריאות נפשית — אך לא ערכי נדל''ן.", "options_analysis": ["מוזכר בפסקה במפורש", "נכון! לא מוזכר כלל בפסקה", "מוזכר בפסקה במפורש", "מוזכר בפסקה במפורש"]}', 1.22, 1.0, 0.25, 4, 'ai', NULL, true),
('79d9dceb-b79d-4b3a-9959-a09919b82843', 'reading_comprehension', 'What is the passage mainly about?', 'a62091fc-986a-472a-a261-8a659ab696d9', '[{"id": "d", "text": "A guide to teaching cursive handwriting effectively"}, {"id": "a", "text": "Why calculators improved mathematics education"}, {"id": "b", "text": "The debate over whether handwriting instruction should decline as technology advances"}, {"id": "c", "text": "The history of handwriting throughout the centuries"}]'::jsonb, 2, '{"strategy": "שאלת רעיון מרכזי — הפסקה מציגה שני צדדים בוויכוח על מקום הכתיבה ביד בעידן הדיגיטלי.", "correct_reason": "כל הפסקה בנויה סביב הוויכוח בין הסתגלות טכנולוגית טבעית לבין חשש מהשלכות בלתי מכוונות.", "options_analysis": ["לא הנושא, רק פרט משני", "לא הנושא המרכזי, רק אנלוגיה שמוזכרת", "נכון! הוויכוח על מקום הכתיבה ביד מול התקדמות טכנולוגית = הנושא הכולל", "לא נאמר בפסקה כסקירה היסטורית"]}', 1.49, 1.0, 0.25, 4, 'ai', NULL, true),
('efb70cd2-c88f-4fa2-bdc1-98a459e44c47', 'reading_comprehension', 'According to the passage, what do some educators compare the decline of handwriting to?', 'a62091fc-986a-472a-a261-8a659ab696d9', '[{"id": "a", "text": "How smartphones replaced landline telephones"}, {"id": "d", "text": "How cars replaced horses for transportation"}, {"id": "b", "text": "How printing presses replaced handwritten books"}, {"id": "c", "text": "How calculators reduced the emphasis on manual arithmetic"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את ההשוואה המפורשת בפסקה.", "correct_reason": "הפסקה אומרת: ''comparable to how calculators reduced the emphasis on manual arithmetic''.", "options_analysis": ["לא נאמר בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה", "נכון! ההשוואה המדויקת מהפסקה"]}', 1.15, 1.0, 0.25, 4, 'ai', NULL, true),
('5b22ead2-e816-4163-9d77-290f667402e3', 'reading_comprehension', 'The word "unintended" in the passage most closely means:', 'a62091fc-986a-472a-a261-8a659ab696d9', '[{"id": "c", "text": "not deliberately planned or expected"}, {"id": "b", "text": "extremely harmful"}, {"id": "a", "text": "officially approved"}, {"id": "d", "text": "financially costly"}]'::jsonb, 0, '{"strategy": "אוצר מילים בהקשר — ''unintended consequences'' מתייחס לתוצאות שלא תוכננו.", "correct_reason": "unintended = לא מכוון/לא מתוכנן מראש.", "options_analysis": ["נכון! unintended = לא מכוון/לא צפוי מראש", "לא קשור למשמעות המילה — ''unintended'' לא אומר בהכרח מזיק", "לא קשור למשמעות המילה", "לא קשור למשמעות המילה"]}', 1.0, 1.0, 0.25, 4, 'ai', NULL, true),
('8a49c1b3-162f-4a31-97ca-59ff69951108', 'reading_comprehension', 'What cognitive benefit does the passage associate with handwriting?', 'a62091fc-986a-472a-a261-8a659ab696d9', '[{"id": "c", "text": "Increasing typing speed"}, {"id": "d", "text": "Potentially strengthening memory retention and fine motor skills"}, {"id": "b", "text": "Reducing screen time significantly"}, {"id": "a", "text": "Improving spelling accuracy only"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את התועלת הקוגניטיבית שמוזכרת בפסקה.", "correct_reason": "הפסקה אומרת: ''potentially strengthening memory retention and fine motor skills''.", "options_analysis": ["לא נאמר בפסקה — כתיבת יד לא קשורה למהירות הקלדה", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה כהגבלה יחידה"]}', 1.49, 1.0, 0.25, 4, 'ai', NULL, true),
('c95f458f-130b-4e1d-b5ac-28c9caea891a', 'reading_comprehension', 'Why are historians and archivists concerned about the decline of cursive instruction?', 'a62091fc-986a-472a-a261-8a659ab696d9', '[{"id": "c", "text": "Cursive writing is required by international law"}, {"id": "b", "text": "Digital documents cannot be preserved for future generations"}, {"id": "d", "text": "Future generations may struggle to read historical documents written in cursive"}, {"id": "a", "text": "Archivists prefer typed documents over handwritten ones"}]'::jsonb, 2, '{"strategy": "שאלת סיבה — חפש את החשש המפורש בפסקה.", "correct_reason": "הפסקה אומרת: ''raising concerns...about future generations'' ability to read historical documents written in cursive script''.", "options_analysis": ["לא נאמר בפסקה", "לא נאמר בפסקה", "נכון! החשש המדויק שמוזכר בפסקה", "לא נאמר בפסקה"]}', 1.03, 1.0, 0.25, 4, 'ai', NULL, true),
('65eeb231-ea01-4cd4-87e6-665b3a279e6b', 'reading_comprehension', 'What compromise have some schools adopted, according to the passage?', 'a62091fc-986a-472a-a261-8a659ab696d9', '[{"id": "d", "text": "Teaching only cursive handwriting and no typing"}, {"id": "c", "text": "Banning all use of computers in classrooms"}, {"id": "a", "text": "Removing handwriting instruction completely"}, {"id": "b", "text": "Teaching basic handwriting while focusing mainly on digital literacy"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את הפתרון המוזכר בסוף הפסקה.", "correct_reason": "הפסקה אומרת: ''teaching basic handwriting skills while dedicating most instructional time to digital literacy''.", "options_analysis": ["לא נאמר בפסקה — סותר את האיזון המתואר", "לא נאמר בפסקה", "סותר את הפסקה — עדיין מלמדים כתיבת יד בסיסית", "נכון! הפשרה המדויקת שמוזכרת בפסקה"]}', 1.02, 1.0, 0.25, 4, 'ai', NULL, true);